import numpy as np
import torch

from thermal_research.models.translator import SpecOperator, Translator
from thermal_research.physics.spectral import SpectralHeat
from thermal_research.training.calibrate import CalibConfig, TranslatorModel

PITCH = 50e-6


def _synthetic(n=120, H=20, W=16, seed=0):
    """Ground truth generated by the same model family: 2 blocks driven by 2 features."""
    rng = np.random.default_rng(seed)
    spec = SpectralHeat(H, W, PITCH)
    B = np.zeros((2, H, W))
    B[0, 3:8, 2:7] = 1.0
    B[1, 12:18, 9:15] = 1.0
    X = rng.normal(size=(n, 4))
    a = np.log1p(np.exp(np.column_stack([1.5 * X[:, 0], -1.0 * X[:, 1] + 0.5])))
    q = np.einsum("nk,khw->nhw", a, B) * 2e5
    th = spec.steady(torch.tensor(q), torch.tensor(0.075), torch.tensor(800.0)).numpy()
    return X, (40.0 + th).astype(np.float32), (H, W)


def test_translator_shapes_and_linearity():
    spec = SpectralHeat(10, 8, PITCH)
    heat = SpecOperator(spec, G=0.075, h_init=800.0)
    tr = Translator(5, K=3, out_hw=(10, 8), low_hw=(5, 4)).double()
    T, aux = tr(torch.randn(7, 5, dtype=torch.float64), heat)
    assert T.shape == (7, 10, 8) and aux["B"].shape == (3, 10, 8)
    assert torch.all(aux["a"] >= 0) and torch.all(aux["B"] >= 0)


def test_translator_fits_model_consistent_data():
    X, Y, hw = _synthetic()
    cfg = CalibConfig(K=3, low_hw=(10, 8), steps=800, lr=5e-2, tv=0.0, l1=0.0)
    m = TranslatorModel(lambda: SpecOperator(SpectralHeat(*hw, PITCH), 0.075, 500.0), cfg, hw, PITCH, 0.075, 500.0)
    m.fit(X[:90], Y[:90], val=(X[90:100], Y[90:100]))
    err = np.sqrt(((m.predict(X[100:]) - Y[100:]) ** 2).mean())
    spread = Y[100:].std()
    assert err < 0.25 * spread, (err, spread)
    assert m.power_maps(X[:2]).min() >= 0
